// Interpreta el comando de cancelación. El orquestador ya filtró que
// comando === 'cancelar'; a este sub-flujo solo le llegan estas formas de
// texto:
//
//   'cmd:cancelar'                    -> listar los turnos activos del chat
//   'cmd:cancelar:turno_id:<id>'      -> pedir confirmación antes de cancelar
//   'cmd:cancelar:confirmado:<id>'    -> ejecutar la cancelación
//
// Cualquier otra cosa (el botón del menú "/cancelar", el texto libre
// "cancelar", "dar de baja", o incluso el formato viejo "cancelar:14" que el
// orquestador todavía parsea por compatibilidad) cae en 'listar'. El id que
// pudiera venir pegado a un texto tipeado se ignora a propósito: pedirle a
// un paciente el ID de su turno es pedirle un dato que no tiene, y ya no
// existe ninguna forma tipeada de saltarse la lista.
//
// El botón del recordatorio también manda 'cmd:cancelar:turno_id:<id>', así
// que también pasa por 'confirmar' -- cancelar es irreversible para el
// paciente y un toque accidental no debe costarle el turno.
const input = ($input.all()[0] && $input.all()[0].json) || {};
const chatId = input.chat_id;
const comando = input.comando || 'cancelar';
const text = String(input.text || '');

let accion = 'listar';
let turnoId = '';

if (text.startsWith('cmd:cancelar:turno_id:')) {
  accion = 'confirmar';
  turnoId = text.substring('cmd:cancelar:turno_id:'.length).trim();
} else if (text.startsWith('cmd:cancelar:confirmado:')) {
  accion = 'ejecutar';
  turnoId = text.substring('cmd:cancelar:confirmado:'.length).trim();
}

// Callback malformado (turno_id vacío) -> no hay nada que confirmar ni
// ejecutar, se degrada a mostrar la lista en vez de romper río abajo.
if (accion !== 'listar' && !turnoId) {
  accion = 'listar';
}

return [{
  json: {
    chat_id: chatId,
    comando: comando,
    accion: accion,
    turno_id: turnoId
  }
}];

// Arma la lista de turnos activos como un botón por turno, con fecha y
// hora legibles. El id NUNCA se muestra en el texto: viaja escondido en el
// callback_data ('cmd:cancelar:turno_id:<id>'). Un chat puede tener más de
// un turno activo (una madre reservando para ella y para su hijo), por eso
// esto es una lista y no una asunción de turno único.
let chatId = null;
try {
  chatId = $('Code - Decidir Paso').first().json.chat_id;
} catch (e) {}

const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];

// Se arma la fecha con Date.UTC y se lee con getUTCDay(): así el día de la
// semana no depende del timezone del servidor donde corre n8n. Los datos
// (fecha, hora_inicio) ya vienen en hora local del profesional -- esto no
// convierte ningún horario, solo le da forma legible a lo que llegó.
function formatearFechaHora(fecha, horaInicio) {
  const partes = String(fecha).split('-').map(Number);
  const y = partes[0], m = partes[1], d = partes[2];
  const dia = DIAS[new Date(Date.UTC(y, m - 1, d)).getUTCDay()];
  const hhmm = String(horaInicio || '').slice(0, 5);
  return dia + ' ' + String(d).padStart(2, '0') + '/' + String(m).padStart(2, '0') + ' · ' + hhmm;
}

const input = ($input.all()[0] && $input.all()[0].json) || {};
let turnos = input.body;
if (!Array.isArray(turnos)) turnos = [];

const inlineKeyboard = turnos.map(function (t) {
  return [{
    text: formatearFechaHora(t.fecha, t.hora_inicio),
    callback_data: 'cmd:cancelar:turno_id:' + t.id
  }];
});

return [{
  json: {
    chat_id: chatId,
    cantidad: turnos.length,
    mensaje: turnos.length > 0 ? '¿Cuál turno querés cancelar?' : 'No tenés turnos para cancelar.',
    inline_keyboard: inlineKeyboard
  }
}];

// Busca el turno elegido dentro de la lista de turnos activos, para poder
// mostrar fecha y hora en la pregunta de confirmación (nunca el ID).
//
// Se vuelve a consultar /turnos/activos en vez de confiar ciegamente en el
// id que viajó en el callback: entre que se mostró el botón y que el
// paciente lo tocó, el turno pudo haberse cancelado o vencido. Si ya no
// está en la lista de activos, se avisa en vez de intentar confirmar una
// cancelación sobre un turno que ya no corresponde.
//
// chat_id y turno_id se leen por nodo nombrado porque este código corre
// DESPUÉS de un nodo HTTP: la respuesta HTTP reemplazó el item y no trae
// esos campos.
let chatId = null;
let turnoId = '';
try {
  const decidido = $('Code - Decidir Paso').first().json;
  chatId = decidido.chat_id;
  turnoId = decidido.turno_id || '';
} catch (e) {}

const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
function formatearFechaHora(fecha, horaInicio) {
  const partes = String(fecha).split('-').map(Number);
  const y = partes[0], m = partes[1], d = partes[2];
  const dia = DIAS[new Date(Date.UTC(y, m - 1, d)).getUTCDay()];
  const hhmm = String(horaInicio || '').slice(0, 5);
  return dia + ' ' + String(d).padStart(2, '0') + '/' + String(m).padStart(2, '0') + ' · ' + hhmm;
}

const input = ($input.all()[0] && $input.all()[0].json) || {};
let turnos = input.body;
if (!Array.isArray(turnos)) turnos = [];

const turno = turnos.find(function (t) { return String(t.id) === String(turnoId); });

return [{
  json: {
    chat_id: chatId,
    turno_id: turnoId,
    encontrado: !!turno,
    fecha_hora_legible: turno ? formatearFechaHora(turno.fecha, turno.hora_inicio) : ''
  }
}];

// Lee el resultado de PUT /turnos/{id}/cancelar y arma la respuesta.
//
// chat_id y turno_id se leen por nodo nombrado (Code - Decidir Paso) porque
// este código corre DESPUÉS de HTTP - PUT Cancelar: la respuesta HTTP
// reemplaza el item y no trae esos campos.
//
// neverError + fullResponse en el nodo HTTP son obligatorios: sin ellos un
// 404/409 tira excepción, este código nunca corre, y el paciente recibe
// silencio en vez de un mensaje.
let chatId = null;
let turnoIdSolicitado = '';
try {
  const decidido = $('Code - Decidir Paso').first().json;
  chatId = decidido.chat_id;
  turnoIdSolicitado = decidido.turno_id || '';
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};
const ok = typeof statusCode === 'number' && statusCode >= 200 && statusCode < 300;

// El id se toma de la respuesta cuando el backend la devuelve; si el turno
// no existe no hay body, y se usa el que se pidió cancelar para que el
// mensaje siga diciendo de qué turno habla.
const turnoId = body.id || turnoIdSolicitado;

let mensaje;
if (ok) {
  mensaje = '✅ Turno #' + turnoId + ' cancelado. El horario vuelve a estar disponible.';
} else if (statusCode === 404) {
  mensaje = 'No encontramos ese turno. Puede que ya lo hayan cancelado. Volvé a pedir la lista.';
} else if (statusCode === 409) {
  mensaje = 'Ese turno ya estaba cancelado, o no se puede cancelar en su estado actual.';
} else {
  const detalle = body.detail ? (' (' + body.detail + ')') : '';
  mensaje = 'No pudimos cancelar el turno' + detalle + '. Intentá de nuevo en un rato.';
}

return [{
  json: {
    chat_id: chatId,
    turno_id: turnoId,
    exito: ok,
    mensaje: mensaje
  }
}];
